INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1254209-cie410', 'stk-blood_prince', 'CIE 410', 'info', '{"desc": "CISE 313 Automation Devices and Electronics\nPrerequisite: EE203\n\nهذي المادة ماليها كتاب خاص … فيعتمد على الدكتور الي يدرسها … هو يحدد المراجع والكتب للمادة\n\nالكلام المسجل عندنا بالسيلابوس انه المفروض ثلاثة كتب هي :\n\nTerry Bartlet, “Industrial Automated Systems: Instrumentation and Motor Control”, Delmar Cengage Learning, 1st edition, 2011\n\nKilian, “Modern Control Technology”, Delmar Cengage Learning, 3rd Edition, 2006\n\nRobert Bateson, “Introduction to Control System Technology”, 7th edition, 2002\n\nطبعا هذي المادة تعتبر المستوى الاول لدراسة الإنسترومنت بحيث تهتم ببعض المواضيع والأجهزة المتعلقة بالانسترومنت\nفي البداية راح تكون المواضيع عن ( Signal conditioning & conversions) وكيف يكون … وليش ضروري للتحكم\nوبعدين مواضيع متفرقة عن (Actuators) و (Final-control elements) بعد كدا راح يتكلم عن بعض الأجهزة الالكتروميكانيكية و أنواع مختلفة من السويتش (Switch)\nيمكن تستغربوا من السويتش 😁 لكنه موضوع مهم وكبير ومتفرق وفيه انواع كثيرة … مثلا\n(Temperature Switch , Pressure Switch)\n\nبعدها راح ترجعوا شوي إلى EE 203 بس بشكل متخصص من ناحية الإنسترومنت وراح يتكلم المنهج عن (Diodes, Transistors, MOSFET) بالإضافة إلى بعض الأجهزة الإليكترونية الأخرى\n\nوبعدها راح يتركز المنهج على دراسة المحركات (Motors) من ناحية أنواعها وكيفية عملها\n\nفي النهاية راح ينتهي المنهج بدراسة المبادئ الأساسية لل (Hydraulic & Pneumatic ) وكيف نقدر نستخدمهم في التحكم بال (Valves and Actuators) ويمكن بعدها تدرسوا بعض النماذج الواقعية وتحليلها وكيفية عمل المواضيع الى درستها من هذي المادة\n\n🤪\nيمكن حسيتوا المواضيع واجد وصايرة المادة ما تمشي بتناسق معين\n🤠 كلام سليم … لأن الغاية من المادة إنك تعرف الأشياء المتعلقة بالإنسترومنت … والإنسترومنت متعلق بأشياء لا تحصى … وكل ما تقدم العمر طلعت تكنلوجيا جديدة\nطبعا هنا يجي دور الدكتور عشان يبين لك الترابط بين الأجهزة الكهروميكانيكية/ الميكانيكية/الكهربئية وبين الإنسترومنت … وكيف نقدر نستخدمهم في هذا المجال\nطبعا هالشي صعب … خصوصا إذا كانت خلفية الدكتور إلكتريك … لأن بياخذها من منظور الإلكتريك … فهنا يبي لك شوي تعتمد على حالك 👍 الشغلة مي صعبة بس يبي لها اطلاع … عن نفسي … فهمت هذا الترابط في أيام الكواب 🤠\n\nباقي اللاب … في اللاب راح تكون المواضيع نوعا ما متعلقة باللكشر (لكن ليس كليا) وعادة الدكتور يختار الي يحسه يناسب الطلاب … احنا كان يسألنا ويختار المواضيع الي يشوفها أحسن\n\nإذا دخلتوا لاب 340B راح تشوفوا جهاز فيه قطع بلاستيك وحديد وفيه حزام حمل … إن شاء الله راح تشغلوه في هذا الكورس … وتخلوه اوتماتيكيا يفصل بين الحديد والبلاستيك\nوباقي اللابات تاخذ نفس المنوال … الي هي تطوير أفكارك باستخدام الأجهزة الموجودة على أٍساس تبني نظام خاص … يقوم بالعمليات اوتوماتيكيا\nالبعض يكون (Hardware & Software) والآخر (Software)\nوفيه بعض اللابات راح تركز شوي على (Motors)\nفي النهاية في وجهة نظري هذا اللاب مهم وبساعدك بعدين إن شاء الله 😆", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-410-automation-devices-and-electronics/120898/3", "user": "blood_prince", "ts": 1377073444000, "tid": 120898, "pn": 3}}', 1377073444000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437937-cie410', 'stk-user8581', 'CIE 410', 'info', '{"desc": "ماقصر blood prince تقريبا غطى كل مواضيع الكورس فكلامي بيكون على اللاب والبروجكت …\nتقريبا الى نص السمستر راح يكون اللاب عن البرمجة < PLC PROGRAMMING > ويكون على برنامج LogixPro 500 PLC Simulator\nوالنص الثاني كان مواضيع له علاقة بالليكشر و الـ power electronics\n\nفي اللاب في 2 mini projects\n- الأول هو برمجة dual conveyor system بحيث يفصل بين قطع البلاستيك والحديد ,شرح البروجكت بيكون في الملف الي في نهاية هذا الرد\nصورة لل dual conveyor\nhttp://www.italtec.it/gif/dualcon.gif\n\n-البروجكت الثاني الخيار فيه مفتوحة للطلاب اهم شي يكون له علاقة بالي تأخذه في الليكشر وهذي قائمة بالمشاريع ارسلها د.ميسورولا و الأهم ماتستخدم micro controller\nhttp://store1.up-00.com/2016-01/145184253832541.png\n\n- الكتاب ما استخدمناه كثير … صحيح هو طويل و يسترسل في بعض المواضيع لكن اشوفه جيد كمرجع وفيه معلومات مفيدة جدا لكنه مايصلح للطلاب وعشان كذا كان الدكتور يشرح من السلايدات و الهانداوت.\n- اللاب كان فيه بعض القطع خربانة … فبعد ماتشيك السيركت حاول تغير بعض القطع او الاجهزة مثلا الـ oscilloscope او الـ motors يمكن خربانة\n- الكورس ممتع خاصة في البروجكت + القسم الأول في اللابات اما القسم الثاني الي كان على هاردوير ما استفدت الصراحة كثير لأن بعض القطع كانت خربانة + كنا نضيع وقت كبير وفي النهاية مايمدينا نخلص اللاب وفي النهاية نضطر انه نلفق في الريبورت .\n- الكورس يعتمد على الدكتور الي ينزله , مع ميسورلا اتوقع لأن الافرج كان عالي تقريبا 80% ف القريدات كانت ستنادرد\n\nهذا الرابط فيه :\nhttp://www.mediafire.com/download/2wnb22fp5seqd01/CISE313-STKFUPM.rar\n- سلاباس 151\n- لاب مانوال ( الموجود في موقع القسم قديم وفيه اختلاف كبير)\n- مانوال سلوشن .\n- سلايدات + الهانداوات لـ د.ميسورولا.\n- كويزات وهوموركات مع السلوشن .\n\n- البرنامج logix 550 pro simulator ( لللاب )\n\nhttp://thelearningpit.com/lp/logixpro.html", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-410-automation-devices-and-electronics/120898/5", "user": "user8581", "ts": 1451857440000, "tid": 120898, "pn": 5}}', 1451857440000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1504022-cie410', 'stk-ali_g', 'CIE 410', 'info', '{"desc": "مع د.ميسورولا في ترم 181\n\nجودة المقرر بشكل عام:\nتنظيم المنهج متعوب عليه\n\nالمواضيع التي يغطيها المقرر:\n15% (Major 1)\n1-Introduction to Final-Control: راح يعطيك نبذة كاملة عن الكورس عن مكونات النظام controller, actuator, Plant, measurnment system والخ\n2-Relays and switches :في ايام الجاهلية كان السويتش ميكانيكي موجود عشان نخليه اوتوماتيكي\nنحتاج electric signal عشان يستجيب السويتش وهنا تاجي فكرة electro magnetic relay, الخطوة الثانية الناس فكرو ليه ما نتحكم multi relays بMicrocontroller وكذا طلع\nPLC, بس في سلبية في relay صح انه يحمل تيار عالي بس انه بطيء وحجمه كبير, فكذا جت فكرة BJT as switching Mode, وانتشرت تطبيقات الالكترونيك سويتش في جوالات والحاسبات الى ما لا نهاية.\nهذي نبذة بسيطة عن التطور في موضوع السويتش وراح تتعلم قطرة من بحر .\n\n20% (Major 2)\n3- Solid-state Switching Circuits: في بداية يعرفك انواع electronic semiconductors غير عن BJT, MOSFET, JFET, الي هم SCR, DIAC, TRIAC, GTO بعدها تخش في موضوع RMS و Average فتحتاج ماث شوية عشان تحسبهم وكيف تتحكم فيهم وبعدها راح تتطرق بانواع من convertor\nDC/DC chopper, AC/AC, AC/DC, DC/AC, بعدها راح تدرس H-bridge من تطبيقاته L298 في اردوينو Motor DC\n\n%20 (Major 3)\n4- Electric Motors: الموتر ينقسم الى الجزئية الكهربائي بسبب تاثير الكترومقناتيك قدرنا نولد جزء ميكانيكي له عزم وسرعة معين فممكن نحتاج gear عشان mechanical load.\nالكتريك موتر يعتمد سرعته على فولت, في طريق تتحكم فيه زي مثلا تغير تيار بتغير المقاومة ولكن هذي الطريقة سيئة بسبب الكفاءة, ولكن باستخدام DC/DC Chopper كذا تحافظ كفاءة الموتر, الموتر انواع راح تدرس فيها.\n\n%15 (Final)\n5- Fluids: نبي نتحكم في fuild فنحتاج موتر عشان نتحكم في valve controller.\nراح تحتاج me203 شوية بسبب قوانين.\n\nالكتاب المستخدم للمقرر:\nشرحه ممتاز الكتاب .\n\nالأسئلة والأمثلة المستخدمة في المقرر:\nتمرن على اسئلة اخر كتاب مهمة, السلوشن حق الكتاب في الرابط\n\nمدى فائدته في الناحية التطبيقية:\n1- راح تتعلم PLC وهذا الى لان يستخدم في الاشارات المرور وغيرها, تقدر تبحث وتحصل كلام افضل مني.\n2- H-bridge تتحكم في سرعة واتجاه الموتر.\n3- Power electronics وهذا له فيلد خاص في قسم الكهرباء في موضوع microgird PV DC تحتاج DC/DC Convertor وبور الكترونيك له تطبيقات كثيرة تقدر تطلع عليه.\n\nإضافات:\n1- تصحيح الدكتور مشدد يحاسبك بملي.\n2- الدكتور شرحه بطل وما شاء الله فاهم ميكاترونيك.\n3- اللاب من سلبياته انه فيه القطع قديمة وبعضها خربانة, وoscilloscope من موديل 1900 وخشبة.\n4-في كلام من زملائي عن المادة يشوفونها مافيها فائدة وانا عكس كلامهم عشان كذا شرحت وربطت اشياء كثيرة.\n5- المادة ما فيها كويزات.\n6- لا تغيب يوم لكل غياب خصم 0.5%\n\nملفات:\n\nCISE313 - Download - 4shared - ali g\n\nهذي توزيع الدرجات:", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-410-automation-devices-and-electronics/120898/6", "user": "Ali_G", "ts": 1545692308000, "tid": 120898, "pn": 6}}', 1545692308000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
